278| \begin{proposition}[一些常见的氧化剂与还原剂]\label{prop:g11:redox:common}
279| 下列物质在实验室和日常生活中反复出现：
280| \begin{center}
281| \small
282| \begin{tabular}{lll}
283| \hline
284| 物质 & 作用 & 其电对的半反应式 \\
285| \hline
286| 氧气 \ce{O2} & 氧化剂 & \ce{O2 + 4H+ + 4e- <=> 2H2O} \\
287| 氯气 \ce{Cl2} & 氧化剂 & \ce{Cl2 + 2e- <=> 2Cl-} \\
288| 次氯酸根 \ce{ClO-}（漂白剂） & 氧化剂 & \ce{2ClO- + 4H+ + 2e- <=> Cl2 + 2H2O} \\
289| 过氧化氢 \ce{H2O2} & 氧化剂 & \ce{H2O2 + 2H+ + 2e- <=> 2H2O} \\
290| 高锰酸根 \ce{MnO4^-} & 氧化剂 & \ce{MnO4^- + 8H+ + 5e- <=> Mn^{2+} + 4H2O} \\
291| 金属 \ce{M}（\ce{Fe}、\ce{Zn}、\ce{Al}\dots） & 还原剂 & \ce{M^{n+} + $n$ e- <=> M} % ce-unbalanced-ok (generic)
292| \\
293| 碘离子 \ce{I-} & 还原剂 & \ce{I2 + 2e- <=> 2I-} \\
294| 硫代硫酸根 \ce{S2O3^{2-}} & 还原剂 & \ce{S4O6^{2-} + 2e- <=> 2S2O3^{2-}} \\
295| 抗坏血酸 \ce{C6H8O6}（维生素 C） & 还原剂 & \ce{C6H6O6 + 2H+ + 2e- <=> C6H8O6} \\
296| \hline
297| \end{tabular}
298| \end{center}
299| \end{proposition}
